<?php require '../includes/functions.php';$u=guard('admin');$from=$_GET['from']??'';$to=$_GET['to']??'';$status=$_GET['status']??'';
$rows=query("SELECT d.*,u.name donor,o.name receiver FROM donations d JOIN users u ON d.donor_id=u.id LEFT JOIN users o ON d.orphanage_id=o.id WHERE (?='' OR DATE(d.created_at)>=?) AND (?='' OR DATE(d.created_at)<=?) AND (?='' OR d.status=?) ORDER BY d.id DESC",[$from,$from,$to,$to,$status,$status])->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="mealbridge-report.csv"');$out=fopen('php://output','w');fputcsv($out,['ID','Title','Donor','Orphanage','Servings','Status','Posted']);foreach($rows as $d){$cells=[$d['id'],$d['title'],$d['donor'],$d['receiver'],$d['quantity'],$d['status'],$d['created_at']];foreach($cells as &$c){$c=(string)$c;if(preg_match('/^[=+@\-\t\r\n]/',$c))$c="'".$c;}unset($c);fputcsv($out,$cells);}fclose($out);exit;}
$title='Donation reports';require '../includes/header.php';?><div class="workspace"><?php require '../includes/sidebar.php';?><section class="workspace-content"><div class="eyebrow">SEE THE DIFFERENCE</div><h1>Donation reports</h1><p>Filter by posting date and status. Export records for your project report.</p><?php require '../includes/report-table.php';?></section></div><?php require '../includes/footer.php';?>